package com.eventhub.service; import com.eventhub.dto.*; import com.eventhub.entity.*; import com.eventhub.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class FeedbackService {private final FeedbackRepository feedback;private final UserRepository users;private final EventRepository events;private final RegistrationRepository registrations;private final AuditLogService audit; @Transactional public FeedbackResponse create(String email,Long eventId,FeedbackRequest r,String ip){User u=user(email);Event e=events.findById(eventId).orElseThrow(()->new IllegalArgumentException("Event not found"));if(e.getStatus()!=EventStatus.COMPLETED)throw new IllegalArgumentException("Feedback is available after event completion");if(feedback.existsByEventIdAndUserId(eventId,u.getId()))throw new IllegalArgumentException("Feedback already submitted");Registration reg=registrations.findByEventIdAndUserId(eventId,u.getId()).orElseThrow(()->new IllegalArgumentException("Only registered attendees can submit feedback"));if(reg.getStatus()!=RegistrationStatus.ATTENDED)throw new IllegalArgumentException("Only attendees can submit feedback");Feedback f=feedback.save(Feedback.builder().event(e).user(u).rating(r.rating()).comment(r.comment()).build());audit.log(u,"FEEDBACK_SUBMITTED","FEEDBACK",f.getId(),ip,"Rating submitted");return FeedbackResponse.from(f);} @Transactional(readOnly=true) public Page<FeedbackResponse> list(Long eventId,int page,int size){return feedback.findByEventIdOrderByCreatedAtDesc(eventId,PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100))).map(FeedbackResponse::from);} @Transactional(readOnly=true) public RatingSummaryResponse summary(Long eventId){return new RatingSummaryResponse(feedback.averageForEvent(eventId),feedback.countByEventId(eventId));} private User user(String e){return users.findByEmailIgnoreCase(e).orElseThrow(()->new IllegalArgumentException("User not found"));}}
